import org.junit.jupiter.api.Test;

class RestrictionGroupCertificateTest {
	@Test
	void onlyWholeGroupsWithRepeatableOrderIndependentAggregatesCanMove() {
		Group group = new Group(new SingletonSet(), List.of("key"), List.of(new GroupElem("n", new Count(null))));
		assertThat(RestrictionModifierRules.wholeGroups(group)).isTrue();
		group.setGroupElements(List.of(new GroupElem("chosen", new Sample(Var.of("v")))));
		assertThat(RestrictionModifierRules.wholeGroups(group)).isFalse();
		group.setGroupElements(List.of(new GroupElem("key", new Count(null))));
		assertThat(RestrictionModifierRules.wholeGroups(group)).isFalse();
		group.setGroupBindingNames(List.of());
		assertThat(RestrictionModifierRules.wholeGroups(group)).isFalse();
	}

	@Test
	void sliceUsesAnExactBoundAndChecksOffsets() {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingSets(List.of(EmptyBindingSet.getInstance(), EmptyBindingSet.getInstance()));
		var union = new Union(new Join(values, new SingletonSet()), new LeftJoin(new SingletonSet(), new EmptySet()));
		assertThat(RestrictionModifierRules.upperBound(union)).isEqualTo(3);
		assertThat(RestrictionModifierRules.noOpSlice(new Slice(union, 0, 2))).isFalse();
		assertThat(RestrictionModifierRules.noOpSlice(new Slice(union, 0, 3))).isTrue();
		assertThat(RestrictionModifierRules.noOpSlice(new Slice(union, 1, 3))).isFalse();
		var scan = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		scan.setResultSizeEstimate(1);
		assertThat(RestrictionModifierRules.noOpSlice(new Slice(scan, 0, 1))).isFalse();
	}
}
